('strategy.experiment_register', 1, '{"action_when_fired": "Re-plan the base without the SLA effect (₹18.15L) and redeploy time to renewals", "bet": "B1 SLA", "boundary_example_80pct_wilson": "10/12 → 0.66-0.93", "change": "63–80%: coach owners; simplify the proposal template", "experiment_id": "EX-B1a", "hypothesis": "A deadline recovers most qualified leads that leaked at the handoff in 2025", "intervention": "Deal ≤ 5 days, proposal ≤ 10 days, alert at day 7, mandatory drop reason, weekly review", "keep_success": "≥ 80% (prior mean)", "kpi_id": "K-B1-02", "owner_role": "Pipeline operations lead", "primary_kpi": "Qualified → proposal within 10 days", "record_class": "operating_plan", "rule_id": "EX-B1a", "rule_status": "approved operating rule [T] (D-010 §5, §7); decision rule on small samples, not a statistical test", "sample_size": "All qualified leads in W1–W4 (about 14 at 2025 pace); decision at n ≥ 12", "source": "D-010 §5 and §7; restated in master report Tables 12.1–12.2", "stop_or_escalate": "< 63% (prior P10): escalate; the base is at risk", "test_population": "Every qualified lead from introductions, creator referrals and the inbound form", "time_limit": "End of W4"}'),
('strategy.experiment_register', 2, '{"action_when_fired": "Base toward ₹18.2L if the SLA fails completely", "bet": "B1 SLA", "boundary_example_80pct_wilson": "5/8 → 0.40-0.80", "change": "0.45–0.60: tighter qualification checklist before forcing proposals", "experiment_id": "EX-B1b", "hypothesis": "Recovered leads still close at a useful rate", "intervention": "As EX-B1a", "keep_success": "≥ 0.60", "kpi_id": "K-B1-03", "owner_role": "Pipeline operations lead", "primary_kpi": "Close rate of recovered proposals", "record_class": "operating_plan", "rule_id": "EX-B1b", "rule_status": "approved operating rule [T] (D-010 §5, §7); decision rule on small samples, not a statistical test", "sample_size": "≥ 8 decided recovered proposals", "source": "D-010 §5 and §7; restated in master report Tables 12.1–12.2", "stop_or_escalate": "< 0.45: stop forcing proposals on recovered leads", "test_population": "Proposals on leads recovered by the SLA (the exact flag is to be defined in the Stage 8 data model)", "time_limit": "As soon as n is reached"}'),
('strategy.experiment_register', 3, '{"action_when_fired": "Require 100% upfront for remaining standard deals; hold all branding", "bet": "B2 Cash discipline", "boundary_example_80pct_wilson": "8/10 → 0.60-0.91", "change": "74–85%: change (D-010 names no specific action)", "experiment_id": "EX-B2", "hypothesis": "Advance-at-signing terms get paid quickly", "intervention": "Proforma invoice on signing; reminders on days 3 and 7; branding gated on payment", "keep_success": "≥ 85%", "kpi_id": "K-B2-02", "owner_role": "Finance and collections lead", "primary_kpi": "Advance paid within 7 days", "record_class": "operating_plan", "rule_id": "EX-B2", "rule_status": "approved operating rule [T] (D-010 §5, §7); decision rule on small samples, not a statistical test", "sample_size": "10 deals", "source": "D-010 §5 and §7; restated in master report Tables 12.1–12.2", "stop_or_escalate": "< 74% (prior P10): escalate", "test_population": "The first 10 signings (any channel, including pre-season premium deals)", "time_limit": "7 days after each signing"}'),
('strategy.experiment_register', 4, '{"action_when_fired": "Hold branding; call sponsors; exclude post-fest payers from the North Star forecast", "bet": "B2 Cash discipline", "change": "—", "experiment_id": "EX-B2", "hypothesis": "Advance-at-signing terms get paid quickly", "intervention": "Proforma invoice on signing; reminders on days 3 and 7; branding gated on payment", "keep_success": "≥ 0.85", "kpi_id": "K-G-02", "owner_role": "Finance and collections lead", "primary_kpi": "Collected ÷ signed cash at T−7", "record_class": "operating_plan", "rule_id": "EX-B2 (gate)", "rule_status": "approved operating rule [T] (D-010 §5, §7); decision rule on small samples, not a statistical test", "sample_size": "10 deals", "source": "D-010 §5 and §7; restated in master report Tables 12.1–12.2", "stop_or_escalate": "< 0.85 escalate; < 0.74 the base cash forecast is at risk", "test_population": "The first 10 signings (any channel, including pre-season premium deals)", "time_limit": "7 days after each signing"}'),
('strategy.experiment_register', 5, '{"action_when_fired": "Re-plan the base to ₹19.4L; move up to about 4 pw to creator follow-up", "bet": "B4a Renewals", "boundary_example_80pct_wilson": "8/24 → 0.22-0.46", "change": "4–7: smaller or early-bird package; offer a presenting upgrade if B5 runs", "experiment_id": "EX-B4a", "hypothesis": "A cheap screening call identifies the 2025 sponsors who will return", "intervention": "1.5 h screening call; full cycle only for interested sponsors", "keep_success": "≥ 8 of 24 (prior implies about 10)", "kpi_id": "K-B4a-02", "owner_role": "Partnerships lead", "primary_kpi": "Interested sponsors after screening", "record_class": "operating_plan", "rule_id": "EX-B4a", "rule_status": "approved operating rule [T] (D-010 §5, §7); decision rule on small samples, not a statistical test", "sample_size": "24 calls", "source": "D-010 §5 and §7; restated in master report Tables 12.1–12.2", "stop_or_escalate": "< 4: stop full renewal cycles", "test_population": "All 24 sponsors of 2025", "time_limit": "End of W2"}'),
('strategy.experiment_register', 6, '{"action_when_fired": "—", "bet": "B4b Creators", "change": "3–5: re-brief creators; focus categories", "experiment_id": "EX-B4b", "hypothesis": "New creators generate referred brands within five weeks", "intervention": "Referral kit and simple incentive; referred brands enter the SLA", "keep_success": "≥ 6 (prior mean 5.5)", "kpi_id": "K-B4b-02", "owner_role": "Community lead", "primary_kpi": "New referred brands", "record_class": "operating_plan", "rule_id": "EX-B4b", "rule_status": "approved operating rule [T] (D-010 §5, §7); decision rule on small samples, not a statistical test", "sample_size": "Count of referred brands", "source": "D-010 §5 and §7; restated in master report Tables 12.1–12.2", "stop_or_escalate": "< 3: stop further recruitment; keep active creators", "test_population": "About 10 newly recruited creators", "time_limit": "End of W5"}'),
('strategy.experiment_register', 7, '{"action_when_fired": "Stretch expectation falls toward ₹25.6L", "bet": "B3 VC/alumni", "change": "6–11: work every introduction; release unused reserve to B4b", "experiment_id": "EX-B3a", "hypothesis": "Funds and alumni will commit introductions", "intervention": "Partner deck and ask wave", "keep_success": "≥ 12: keep the reserve of 12", "kpi_id": "K-B3-02", "owner_role": "Network lead", "primary_kpi": "Committed introductions", "record_class": "operating_plan", "rule_id": "EX-B3a", "rule_status": "approved operating rule [T] (D-010 §5, §7); decision rule on small samples, not a statistical test", "sample_size": "Count of committed introductions (named decision-maker who agreed to meet)", "source": "D-010 §5 and §7; restated in master report Tables 12.1–12.2", "stop_or_escalate": "< 6: stop asking after the second wave; reassign the 3.35 pw conditional reserve", "test_population": "8 funds plus an alumni campaign", "time_limit": "End of W2"}'),
('strategy.experiment_register', 8, '{"action_when_fired": "—", "bet": "B3 VC/alumni", "boundary_example_80pct_wilson": "4/6 → 0.41-0.85", "change": "—", "experiment_id": "EX-B3b", "hypothesis": "Introductions turn into meetings", "intervention": "Each worked through the SLA", "keep_success": "≥ 0.62", "kpi_id": "K-B3-03", "owner_role": "Network lead", "primary_kpi": "Introduction → meeting", "record_class": "operating_plan", "rule_id": "EX-B3b", "rule_status": "approved operating rule [T] (D-010 §5, §7); decision rule on small samples, not a statistical test", "sample_size": "≥ 6 introductions", "source": "D-010 §5 and §7; restated in master report Tables 12.1–12.2", "stop_or_escalate": "< 0.62 (prior P10): review introduction quality", "test_population": "Introductions received", "time_limit": "When n is reached"}'),
('strategy.experiment_register', 9, '{"action_when_fired": "Offer interested buyers a free presenting slot", "bet": "B5 Premium", "change": "—", "experiment_id": "EX-B5", "hypothesis": "A ratio-priced rate card sells to renewed sponsors and researched prospects when pitched early", "intervention": "Rate card, title with broad exclusivity planned (narrow sought)", "keep_success": "≥ 3 qualified meetings by W−2; term sheet by W0 = on track (model sells the title in 61% of runs)", "kpi_id": "K-B5-02", "owner_role": "Premium sales pair", "primary_kpi": "Qualified title meetings; term sheet", "record_class": "operating_plan", "rule_id": "EX-B5 title", "rule_status": "approved operating rule [T] (D-010 §5, §7); decision rule on small samples, not a statistical test", "sample_size": "24 pitches; realised ÷ asking price on the first 2 deals", "source": "D-010 §5 and §7; restated in master report Tables 12.1–12.2", "stop_or_escalate": "Unsold at W7 (sell-by): stop the title", "test_population": "12 title pitches and 12 presenting pitches, pre-season", "time_limit": "Title by W7 (sell-by); presenting by W4"}'),
