('strategy.kpi_dictionary', 1, '{"available_in_2025_dataset": "no (no payment data)", "baseline_2025": "unknown; \"≈ ₹17L\" is an assumption", "bet": "All", "data_required": "payments / receipts", "definition": "Cash-type sponsorship received by festival day; in-kind and signed-but-unpaid excluded", "formula": "SUM(receipt.amount) WHERE receipt.date < fest_start AND support_type = cash", "frequency": "weekly", "grain": "season", "kpi_id": "K-NS-01", "kpi_type": "north star", "name": "Cash collected before the fest", "record_class": "operating_plan", "rule_status": "approved targets (D-009)", "source": "D-010 (05_STRATEGY/D010_approved/STRATEGY_SYNTHESIS_DRAFT.md)", "threshold_rule": "Base ₹21.2L (commit) · Plan ₹26.1L (target) · Stretch ₹28.6L (ambition); D-009 scenarios, not thresholds", "unit": "₹ lakh"}'),
('strategy.kpi_dictionary', 2, '{"available_in_2025_dataset": "yes (signed value)", "baseline_2025": "share of final 2025 signed value: 18/37/59/67/85/100%", "bet": "All", "data_required": "opportunity stage versions with confirmed value and date", "definition": "Cumulative confirmed (signed) value from in-window channels at the end of each week W4–W9", "formula": "SUM(confirmed_value) by week ÷ gate", "frequency": "weekly W4–W9", "grain": "week", "kpi_id": "K-G-01", "kpi_type": "gate", "name": "Cumulative signed value vs pacing gate", "record_class": "operating_plan", "rule_status": "approved operating rule [T] (D-010); decision rule, not a statistical test", "source": "D-010 (05_STRATEGY/D010_approved/STRATEGY_SYNTHESIS_DRAFT.md)", "threshold_rule": "Base gates 5.1/10.3/16.2/18.5/23.3/27.6; plan/stretch 6.4/13.0/20.4/23.4/29.4/34.8. W6: ≥ plan gate → on plan; between base and plan → base trajectory, trigger B3/B4 contingencies; < 0.8 × base gate → re-plan to downside", "unit": "₹ lakh"}'),
('strategy.kpi_dictionary', 3, '{"available_in_2025_dataset": "no", "baseline_2025": "prior mean 0.85 (P10 0.74) [A]", "bet": "B2", "data_required": "payments, signed cash", "definition": "Cash collected ÷ cash-type signed value, seven days before the fest", "formula": "collected_cash ÷ signed_cash_type", "frequency": "at T−7 (tracked weekly from W4)", "grain": "season", "kpi_id": "K-G-02", "kpi_type": "gate", "name": "Collected ÷ signed cash at T−7", "record_class": "operating_plan", "rule_status": "approved operating rule [T] (D-010); decision rule, not a statistical test", "source": "D-010 (05_STRATEGY/D010_approved/STRATEGY_SYNTHESIS_DRAFT.md)", "threshold_rule": "Keep ≥ 0.85; escalate < 0.85 (hold branding, call sponsors); < 0.74 → base cash forecast at risk", "unit": "ratio"}'),
